const assert = require('node:assert/strict');
const fs = require('node:fs');

const view = fs.readFileSync('package/luci-app-telego/htdocs/resources/view/telego/nginx-files.js', 'utf8');
const menu = JSON.parse(fs.readFileSync('package/luci-app-telego/root/usr/share/luci/menu.d/telego.menu.json', 'utf8'));
const acl = JSON.parse(fs.readFileSync('package/luci-app-telego/root/usr/share/rpcd/acl.d/luci-app-telego.json', 'utf8'))['luci-app-telego'];
const makefile = fs.readFileSync('package/luci-app-telego/Makefile', 'utf8');
const i18nMakefile = fs.readFileSync('package/luci-i18n-telego-ru/Makefile', 'utf8');
const nginxMakefile = fs.readFileSync('package/nginx-telego/Makefile', 'utf8');
const rpc = fs.readFileSync('package/luci-app-telego/root/usr/share/rpcd/ucode/telego-nginx', 'utf8');
const editor = fs.readFileSync('package/nginx-telego/files/usr/libexec/nginx-telego-editor', 'utf8');

const advancedPage = menu['admin/services/telego/advanced'];
assert.ok(advancedPage);
assert.equal(advancedPage.action.type, 'view');
assert.equal(advancedPage.action.path, 'telego/advanced');
assert.equal(advancedPage.order, 15);

const page = menu['admin/services/telego/nginx-files'];
assert.ok(page);
assert.equal(page.action.type, 'view');
assert.equal(page.action.path, 'telego/nginx-files');
assert.equal(page.depends.fs['/usr/libexec/nginx-telego-admin'], 'executable');
assert.equal(page.depends.fs['/usr/libexec/nginx-telego-editor'], 'executable');
assert.equal(page.depends.fs['/usr/share/nginx-telego/ownership.tsv'], 'file');
assert.deepEqual(acl.read.ubus['telego.nginx'], ['inventory', 'managed_content', 'foreign_content', 'foreign_revision', 'platform_status', 'platform_preflight', 'firewall_status', 'firewall_preflight', 'certificate_status', 'certificate_preflight']);
assert.deepEqual(acl.write.ubus['telego.nginx'], ['quarantine', 'restore', 'delete_active', 'delete_quarantined', 'replace_active', 'create_foreign', 'rename_active', 'repair']);
assert.match(makefile, /PKG_RELEASE:=28/);
assert.match(i18nMakefile, /PKG_RELEASE:=22/);
assert.match(nginxMakefile, /PKG_RELEASE:=9/);
assert.match(makefile, /EXTRA_DEPENDS:=telego-pkg \(>=0\.6\.5-r7\)/);
assert.match(makefile, /DEPENDS:=.*\+luci-lib-uqr/);
assert.match(nginxMakefile, /EXTRA_DEPENDS:=nginx-ssl \(>=1\.0\), telego-pkg \(>=0\.6\.5-r7\)/);
assert.match(i18nMakefile, /EXTRA_DEPENDS:=luci-app-telego \(>=0\.6\.5-r28\)/);
assert.match(nginxMakefile, /nginx-telego-editor/);
assert.match(nginxMakefile, /nginx-telego-firewall/);
assert.match(nginxMakefile, /nginx-telego-platform/);
assert.match(nginxMakefile, /nginx-telego-cert/);
assert.match(nginxMakefile, /openssl-util/);

const methods = ['inventory','managed_content','foreign_content','foreign_revision','quarantine','restore','delete_active','delete_quarantined','replace_active','create_foreign','rename_active','repair'];
for (const method of methods) assert.match(rpc, new RegExp('\\b' + method.replace('_', '\\_') + '\\s*:'));
assert.match(rpc, /const EDITOR = '\/usr\/libexec\/nginx-telego-editor'/);
assert.match(rpc, /const PLATFORM = '\/usr\/libexec\/nginx-telego-platform'/);
assert.match(rpc, /const CERTIFICATE = '\/usr\/libexec\/nginx-telego-cert'/);
assert.ok(!rpc.includes('/etc/nginx/conf.d/'));
assert.ok(!rpc.includes("import { open"));
assert.ok(rpc.includes("run_editor_read(['revision', name])"));
assert.ok(rpc.includes("run_editor_write(['replace', name, revision], content)"));
assert.ok(rpc.includes("run_editor_write(['create', name], content)"));
assert.ok(rpc.includes("run_editor_read(['rename', name, new_name, revision])"));
assert.ok(rpc.includes("return 'target-exists'"));
assert.ok(rpc.includes("return 'managed-target'"));
assert.ok(editor.includes('MAX_EDIT_BYTES=65536'));
assert.ok(editor.includes('revision NAME.conf'));
assert.ok(editor.includes('revision_active()'));
assert.ok(editor.includes('file changed since it was opened'));
assert.ok(editor.includes('nginx_test'));
assert.ok(editor.includes('rollback_transaction'));
assert.ok(editor.includes('create NAME.conf'));
assert.ok(editor.includes('rename OLD.conf NEW.conf EXPECTED_SHA256'));

for (const method of methods) assert.ok(view.includes(`method: '${method}'`));
assert.ok(view.includes("'ok': _('In sync')"));
assert.ok(view.includes("file.ownership === 'package' && file.state === 'modified'"));
assert.ok(view.includes("file.ownership === 'generated' && file.state === 'foreign'"));
assert.ok(view.includes("file.kind === 'quarantined' && file.state === 'quarantined'"));
assert.ok(view.includes("actionButton(_('Create file')"));
assert.ok(view.includes("actionButton(_('Edit')"));
assert.ok(view.includes("actionButton(_('Rename')"));
assert.ok(view.includes("callForeignContent(file.name)"));
assert.ok(view.includes("callForeignRevision(file.name)"));
assert.ok(view.includes("callReplaceActive(file.name, revision, edited)"));
assert.ok(view.includes("callCreateForeign(name, content)"));
assert.ok(view.includes("callRenameActive(file.name, newName, revision)"));
assert.ok(view.includes('textarea'));
assert.ok(view.includes("'class': 'telego-responsive-table'"), 'Nginx inventory must scroll inside a bounded region on narrow screens');
assert.ok(view.includes("'scope': 'col'"), 'Nginx inventory headers expose column scope');
assert.ok(view.includes("'for': 'telego-nginx-create-name'"), 'create-file name field has an explicit label');
assert.ok(view.includes("'for': 'telego-nginx-create-content'"), 'create-file editor has an explicit label');
assert.ok(view.includes("'for': 'telego-nginx-rename-name'"), 'rename field has an explicit label');
assert.ok(view.includes("'for': 'telego-nginx-edit-content'"), 'Nginx editor has an explicit label');
assert.ok(view.includes("'aria-describedby': 'telego-nginx-create-content-help'"));
assert.ok(view.includes("'aria-describedby': 'telego-nginx-edit-content-help'"));
assert.ok(!view.includes('form.Value'));
assert.ok(!view.includes('diagnosticsNav'), 'P5.6 removes the Nginx Files diagnostics subtab');
assert.ok(view.includes('This restricted editor can modify only an existing foreign administrator-owned .conf file.'));
assert.ok(view.includes('A new file can be created only as a foreign administrator-owned direct child of /etc/nginx/conf.d/.'));
assert.ok(view.includes('Only an active foreign administrator-owned .conf file can be renamed.'));
assert.ok(view.includes("const errorBox = E('div', { 'class': 'alert-message error'"));
assert.ok(view.includes('createButton.disabled = true'));
assert.ok(view.includes('renameButton.disabled = true'));
assert.ok(view.includes('saveButton.disabled = true'));
assert.ok(view.includes('showInlineError(lifecycleError(result && result.error))'));
console.log('LuCI P10 Nginx foreign lifecycle contract tests passed');
